using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

/// <summary>
/// Shared configuration for all evaluation scenarios.
/// </summary>
internal static class EvalConfig
{
    public static ReportingConfiguration CreateReportingConfig(
        string storagePath,
        IChatClient judgeChatClient)
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return new ReportingConfiguration(
            storagePath,
            evaluators,
            chatConfiguration: new ChatConfiguration(judgeChatClient));
    }
}

using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode – verifies the agentic app emits correct OTel spans for AI operations.
/// </summary>
[TestClass]
public class TelemetryTests
{
    [TestMethod]
    public async Task ChatCompletion_EmitsExpectedSpans()
    {
        var exportedActivities = new List<Activity>();

        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("Azure.*")
            .AddInMemoryExporter(exportedActivities)
            .Build();

        // Arrange: build a client pipeline with telemetry enabled
        IChatClient client = new ChatClientBuilder(CreateTestClient())
            .UseOpenTelemetry(sourceName: "Microsoft.Extensions.AI")
            .Build();

        // Act
        var response = await client.GetResponseAsync("What is 2+2?");

        // Assert: at least one span was recorded
        tracerProvider.ForceFlush();
        Assert.IsTrue(exportedActivities.Count > 0, "Expected at least one telemetry span.");

        var chatSpan = exportedActivities.FirstOrDefault(a => a.DisplayName.Contains("chat"));
        Assert.IsNotNull(chatSpan, "Expected a span containing 'chat' in its name.");
    }

    [TestMethod]
    public async Task ChatCompletion_SpanContainsModelAttribute()
    {
        var exportedActivities = new List<Activity>();

        using var tracerProvider = Sdk.CreateTracerProviderBuilder()
            .AddSource("Microsoft.Extensions.AI")
            .AddInMemoryExporter(exportedActivities)
            .Build();

        IChatClient client = new ChatClientBuilder(CreateTestClient())
            .UseOpenTelemetry(sourceName: "Microsoft.Extensions.AI")
            .Build();

        await client.GetResponseAsync("Hello");

        tracerProvider.ForceFlush();

        var span = exportedActivities.FirstOrDefault();
        Assert.IsNotNull(span);

        var modelTag = span.Tags.FirstOrDefault(t => t.Key == "gen_ai.request.model");
        Assert.IsNotNull(modelTag.Value, "Span should include gen_ai.request.model attribute.");
    }

    private static IChatClient CreateTestClient()
    {
        // Returns a simple test client that echoes back.
        // Replace with a real endpoint via environment variable for integration runs.
        var endpoint = Environment.GetEnvironmentVariable("EVAL_CHAT_ENDPOINT");
        if (!string.IsNullOrEmpty(endpoint))
        {
            return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(
                    Environment.GetEnvironmentVariable("EVAL_CHAT_KEY") ?? "test"))
                .GetChatClient("gpt-4o-mini")
                .AsIChatClient();
        }

        return new TestChatClient();
    }
}

