                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(
                    Environment.GetEnvironmentVariable("EVAL_JUDGE_KEY") ?? ""))
                .GetChatClient("gpt-4o")
                .AsIChatClient();
        }

        // Fallback: use a test double for offline/unit scenarios
        return new TestChatClient();
