using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode – runs the same scenarios against two model configurations and
/// reports side-by-side quality metrics for regression detection.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "compare");

    [TestMethod]
    public async Task CompareBaseline_vs_Candidate()
    {
        IChatClient judgeClient = CreateJudgeClient();

        var baselineConfig = EvalConfig.CreateReportingConfig(
            Path.Combine(StoragePath, "baseline"), judgeClient);

        var candidateConfig = EvalConfig.CreateReportingConfig(
            Path.Combine(StoragePath, "candidate"), judgeClient);

        var prompt = new List<ChatMessage>
        {
            new(ChatRole.User, "Give me a brief motivational tip for staying focused.")
        };

        // Run baseline
        var baselineResults = await RunScenario(baselineConfig, "Compare_Baseline", prompt, CreateBaselineClient());

        // Run candidate
        var candidateResults = await RunScenario(candidateConfig, "Compare_Candidate", prompt, CreateCandidateClient());

        // Compare: candidate should not regress below baseline
        for (int i = 0; i < baselineResults.Count; i++)
        {
            if (baselineResults[i] is NumericMetricResult baseNum &&
                candidateResults[i] is NumericMetricResult candNum)
            {
                var baseRating = baseNum.NumericInterpretation?.Rating ?? EvaluationRating.Inconclusive;
                var candRating = candNum.NumericInterpretation?.Rating ?? EvaluationRating.Inconclusive;

                Assert.IsTrue(
                    candRating >= baseRating,
                    $"Regression in '{baseNum.MetricName}': baseline={baseRating}, candidate={candRating}");
            }
        }
    }

    private static async Task<IReadOnlyList<EvaluationMetricResult>> RunScenario(
        ReportingConfiguration config,
        string scenarioName,
        IList<ChatMessage> messages,
        IChatClient client)
    {
        await using var scenario = await config.CreateScenarioRunAsync(scenarioName: scenarioName);

        var response = await client.GetResponseAsync(messages);
        var modelResponse = response.Messages.Last();

        await scenario.EvaluateAsync(
            messages,
            modelResponse,
            additionalContext:
            [
                new EvaluationContext("grounding",
                    "The response should be a brief, actionable motivational tip about focus.")
            ]);

        return scenario.GetResults();
    }

    private static IChatClient CreateJudgeClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("EVAL_JUDGE_ENDPOINT");
        if (!string.IsNullOrEmpty(endpoint))
        {
            return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(
                    Environment.GetEnvironmentVariable("EVAL_JUDGE_KEY") ?? ""))
                .GetChatClient("gpt-4o")
                .AsIChatClient();
        }

        return new TestChatClient();
    }

    /// <summary>Baseline model (current production configuration).</summary>
    private static IChatClient CreateBaselineClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("EVAL_CHAT_ENDPOINT");
        if (!string.IsNullOrEmpty(endpoint))
        {
            return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(
                    Environment.GetEnvironmentVariable("EVAL_CHAT_KEY") ?? ""))
                .GetChatClient("gpt-4o-mini")
                .AsIChatClient();
        }

        return new TestChatClient();
    }

    /// <summary>Candidate model (the configuration under test).</summary>
    private static IChatClient CreateCandidateClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("EVAL_CANDIDATE_ENDPOINT")
            ?? Environment.GetEnvironmentVariable("EVAL_CHAT_ENDPOINT");
        if (!string.IsNullOrEmpty(endpoint))
        {
            var model = Environment.GetEnvironmentVariable("EVAL_CANDIDATE_MODEL") ?? "gpt-4o-mini";
            return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(
                    Environment.GetEnvironmentVariable("EVAL_CANDIDATE_KEY")
                    ?? Environment.GetEnvironmentVariable("EVAL_CHAT_KEY") ?? ""))
                .GetChatClient(model)
                .AsIChatClient();
        }

        return new TestChatClient();
    }
}

