+        // Compare: candidate should not regress below baseline
+        for (int i = 0; i < baselineResults.Count; i++)
+        {
+            if (baselineResults[i] is NumericMetricResult baseNum &&
+                candidateResults[i] is NumericMetricResult candNum)
+            {
+                var baseRating = baseNum.NumericInterpretation?.Rating ?? EvaluationRating.Inconclusive;
+                var candRating = candNum.NumericInterpretation?.Rating ?? EvaluationRating.Inconclusive;
+
+                Assert.IsTrue(
+                    candRating >= baseRating,
+                    $"Regression in '{baseNum.MetricName}': baseline={baseRating}, candidate={candRating}");
+            }
+        }
+    }
+
+    private static async Task<IReadOnlyList<EvaluationMetricResult>> RunScenario(
+        ReportingConfiguration config,
+        string scenarioName,
+        IList<ChatMessage> messages,
+        IChatClient client)
+    {
+        await using var scenario = await config.CreateScenarioRunAsync(scenarioName: scenarioName);
+
+        var response = await client.GetResponseAsync(messages);
+        var modelResponse = response.Messages.Last();
+
+        await scenario.EvaluateAsync(
+            messages,
+            modelResponse,
+            additionalContext:
+            [
+                new EvaluationContext("grounding",
+                    "The response should be a brief, actionable motivational tip about focus.")
+            ]);
+
+        return scenario.GetResults();
+    }
+
+    private static IChatClient CreateJudgeClient()
+    {
+        var endpoint = Environment.GetEnvironmentVariable("EVAL_JUDGE_ENDPOINT");
+        if (!string.IsNullOrEmpty(endpoint))
+        {
+            return new Azure.AI.OpenAI.AzureOpenAIClient(
+                new Uri(endpoint),
+                new System.ClientModel.ApiKeyCredential(
+                    Environment.GetEnvironmentVariable("EVAL_JUDGE_KEY") ?? ""))
+                .GetChatClient("gpt-4o")
+                .AsIChatClient();
+        }
+
+        return new TestChatClient();
+    }
